-- LOCAL ONLY explicit SCHOOL07 child release; preserved SCHOOL06 package unchanged.
BEGIN;SELECT pg_advisory_xact_lock(hashtextextended('bogunon:school06:install',0));DO $installer$ BEGIN IF current_database()<>'school01a'OR current_setting('bogunon.ws_install_mode',true)IS DISTINCT FROM 'isolated'THEN RAISE EXCEPTION 'local_only';END IF;IF to_regclass('workspace_private.s07_install_manifest')IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM workspace_private.s07_install_manifest WHERE digest='79f338a23ec1940c13d0522f7afaa37e9022d52a70423bd8cbd04b13dd7eab71'AND fingerprint=(SELECT md5(coalesce(jsonb_agg(x ORDER BY x::text)::text,'[]')) FROM(
 SELECT jsonb_build_object('kind','schema','name',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl::text)x FROM pg_namespace WHERE nspname IN('workspace','workspace_private')
