ALTER FUNCTION public.ws_v1_set_inventory_lot_state(uuid,jsonb,bigint,uuid)OWNER TO ws_owner;
DO $$DECLARE f record;a record;BEGIN FOR f IN SELECT p.oid::regprocedure sig,p.proowner,p.proacl FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE(n.nspname='workspace_private'AND left(p.proname,4)='s07_')OR(n.nspname='public'AND p.proname=ANY(ARRAY['ws_v1_list_inventory_items','ws_v1_get_inventory_item','ws_v1_list_inventory_lots','ws_v1_list_inventory_movements','ws_v1_list_inventory_alerts','ws_v1_list_inventory_locations','ws_v1_get_inventory_context','ws_v1_create_inventory_item','ws_v1_edit_inventory_item','ws_v1_save_inventory_location','ws_v1_receive_inventory','ws_v1_use_inventory','ws_v1_adjust_inventory','ws_v1_dispose_inventory','ws_v1_set_inventory_lot_state']::text[]))LOOP
FOR a IN SELECT DISTINCT grantee FROM aclexplode(coalesce(f.proacl,acldefault('f',f.proowner)))WHERE grantee<>f.proowner AND grantee NOT IN(SELECT oid FROM pg_roles WHERE rolname IN('ws_runtime','ws_authz_reader'))LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %s',f.sig,CASE WHEN a.grantee=0 THEN 'PUBLIC'ELSE quote_ident(pg_get_userbyid(a.grantee))END);END LOOP;END LOOP;END$$;
$inventory_body$;CREATE TABLE workspace_private.s07_install_manifest(digest text PRIMARY KEY,fingerprint text NOT NULL,closed_fingerprint text NOT NULL,state text NOT NULL);ALTER TABLE workspace_private.s07_install_manifest OWNER TO ws_owner;ALTER TABLE workspace_private.s07_install_manifest ENABLE ROW LEVEL SECURITY;ALTER TABLE workspace_private.s07_install_manifest FORCE ROW LEVEL SECURITY;REVOKE ALL ON workspace_private.s07_install_manifest FROM PUBLIC,anon,authenticated,ws_runtime,ws_authz_reader;EXECUTE format('GRANT SELECT,INSERT,UPDATE ON workspace_private.s07_install_manifest TO %I',current_user);EXECUTE format('CREATE POLICY s07_installer ON workspace_private.s07_install_manifest TO %I USING(true)WITH CHECK(true)',current_user);INSERT INTO workspace_private.s07_install_manifest VALUES('79f338a23ec1940c13d0522f7afaa37e9022d52a70423bd8cbd04b13dd7eab71',(SELECT md5(coalesce(jsonb_agg(x ORDER BY x::text)::text,'[]')) FROM(
